// ==== Treiber, nicht Teil des Kerns (bau/werkzeuge/zz_bau_b34.py) ====
const lief = (x) => { const v = $(x).isExecuted; if (typeof v !== 'boolean') throw new Error('Hauptlauf - isExecuted nicht verfuegbar'); return v; };
const r = $('Zustand lesen').first().json;
if (r.statusCode !== 200) throw new Error('Hauptlauf - Offene Posten nicht lesbar, HTTP ' + r.statusCode);
const vr = (r.body && r.body.valueRanges) || [];
const opWerte = (vr[0] && vr[0].values) || [];
const tbWerte = (vr[1] && vr[1].values) || [];
const ein = $('Einstellungen prüfen').first().json;
const lauf = $('Lauf vorbereiten').first().json;
const zs = $('Zahlstand lesen').all().map((i) => i.json);
