const zahlstand = zs.filter((j) => j.art === 'zahlstand');
const ab = $('Aufbau prüfen').first().json;
const posten = ab.posten;
const sperre_id = lief('Sperre sicherstellen') ? String($('Sperre sicherstellen').first().json.id || '') : '';
if (ein.modus !== 'trocken' && !sperre_id) throw new Error('Hauptlauf - Sperre-Tabelle ohne ID');
const dt = lief('Sperre lesen') ? $('Sperre lesen').all().map((i) => i.json).filter((z) => z && z.schluessel) : null;
const entwuerfe = dt ? entwurfDaten(dt) : {};
const tbp = pruefeTextbausteine(tbWerte);
const rechnungen = versandstatusKlaerungen(mitZahlstand(baueRechnungen(posten, leseZustand(opWerte), entwuerfe), zahlstand),
  dt, lauf.lauf_id, lauf.zeit_utc, ein.stichtag);
const plan = planeLauf({ kopfzeile: STUFEN_PFLICHTSPALTEN, rechnungen, einstellungen: ein.einstellungen,
  stichtag: ein.stichtag, auszugStand: zst.auszug_stand, textbausteine_fehler: tbp.fehler });
const zeilen = protokollZeilen(plan, { lauf_id: lauf.lauf_id, modus: ein.modus, zeit_utc: lauf.zeit_utc, zeit_berlin: lauf.zeit_berlin },
  zst.protokoll || []);
const LISTE = ['senden', 'entwurf_anlegen', 'entwurf_ersetzen', 'entwurf_senden', 'entwurf_verwerfen', 'wartet', 'uebergabe'];
const versand_liste = ein.modus === 'trocken' ? [] : plan.entscheidungen.map((d, i) => ({ d, i }))
